/* A function, not a constant: evaluated once at parse time it froze the
   legend in whichever language loaded first. */
const CC = () => [
  ["goods",  L("قيمة البضاعة","Goods value"),      "#1F6FB2","#1F6FB2"],
  ["freight",L("الشحن","Freight"),                 "#D0202A","#D0202A"],
  ["duty",   L("الرسوم الجمركية","Customs duty"),  "#00A3A3","#00A3A3"],
  ["vat",    L("ضريبة القيمة المضافة","VAT"),      "#7B5FC0","#7B5FC0"],
  ["fee",    L("الخدمة والامتثال","Service & conformity"),"#C98A14","#C08420"]
];
const money = n => {
  if(!Number.isFinite(n)) return "—";
  const r = Math.round(n*100)/100;
  return (Object.is(r,-0) ? 0 : r).toLocaleString("en-US",{maximumFractionDigits:2});
};
const clampPct = n => !Number.isFinite(n) ? "—"
  : n>9999 ? ">9999%" : n<-999 ? "<-999%" : n.toFixed(1)+"%";

