const CCAT = () => ({
  general:{n:L("عام — أدوات منزلية، قرطاسية، تغليف","General — housewares, stationery, packaging"),notes:[]},
  ict:{n:L("إلكترونيات وأجهزة تقنية واتصالات","Electronics, IT and telecom devices"),notes:[
    ["sa",L("مواصفة SASO 3114:2026 لأجهزة تقنية المعلومات والاتصالات: تنتهي الفترة الانتقالية في 31 أكتوبر 2026، وتصبح إلزامية من 1 نوفمبر 2026. الشهادات الصادرة وفق مواصفة CST رقم GEN-002 يتوقف العمل بها بحلول 31 مارس 2027.","SASO 3114:2026 for ICT equipment: the grace period ends 31 October 2026 and it becomes mandatory from 1 November 2026. Certificates issued under CST GEN-002 are discontinued by 31 March 2027.")],
    ["om",L("الأجهزة الكهربائية منخفضة الجهد والأجهزة المستهلكة للطاقة ضمن نطاق علامة الجودة العُمانية الإلزامية.","Low-voltage electrical and energy-consuming devices fall within the mandatory Omani Quality Mark scope.")]]},
  beauty:{n:L("مستحضرات تجميل وعناية","Cosmetics and personal care"),notes:[
    ["om",L("مستحضرات التجميل ضمن نطاق علامة الجودة العُمانية الإلزامية منذ 1 مارس 2026.","Cosmetics fall within the mandatory Omani Quality Mark scope since 1 March 2026.")],
    ["bh",L("مستحضرات التجميل من الفئات التي تخضع لفحص عند المنفذ.","Cosmetics are among the categories subject to port inspection.")]]},
  food:{n:L("أغذية ومستلزمات مطاعم","Food and restaurant supplies"),notes:[
    ["sa",L("الأغذية والمواد الملامسة للغذاء تخضع للهيئة العامة للغذاء والدواء (SFDA) بالإضافة إلى متطلبات سابر.","Food and food-contact materials fall under the SFDA in addition to the SABER requirements.")]]},
  build:{n:L("مواد بناء ومعادن وحديد","Building materials, metals and steel"),notes:[
    ["sa",L("تتطلب اعتماد نموذج إقرار المنتج أو المستورد من وزارة الصناعة والثروة المعدنية. لا تُصدر شهادة الإرسالية قبل إدراج الإقرار المعتمد في الملف الفني، والإقرار صالح 60 يومًا فقط من تاريخ إصداره.","These require an approved Producer/Importer Declaration form from the Ministry of Industry and Mineral Resources. The Shipment CoC is not issued until the approved declaration is in the technical file, and the declaration is valid for only 60 days from issue.")]]}
});

function bindCompliance(){
  const J=CJUR(), C=CCAT();
  const out=document.getElementById("cq_out");
  const draw=()=>{
    const jk=document.getElementById("cq_j").value, ck=document.getElementById("cq_c").value;
    const j=J[jk], c=C[ck];
    const notes=(c.notes||[]).filter(n=>n[0]===jk).map(n=>n[1]);
    out.innerHTML=`<div class="card" style="max-width:820px;margin-inline:auto">
      <span class="eyebrow" style="margin-bottom:6px">${j.n} · ${c.n}</span>
      <h3 style="margin-top:0">${j.body}</h3>
      <ul style="margin:14px 0 0;padding-inline-start:20px;display:grid;gap:8px;font-size:.94rem">
        ${j.req.map(r=>`<li>${r}</li>`).join("")}
      </ul>
      <div class="info" style="margin-top:18px">${j.tax}</div>
      ${j.rf?`<p class="muted" style="font-size:.9rem;margin-top:12px">${j.rf}</p>`:""}
      ${notes.length?`<div class="notice" style="margin-top:14px"><strong>${L("تنبيه ساري:","Live alert:")}</strong> ${notes.join(" ")}</div>`:""}
    </div>`;
  };
  document.getElementById("cq_j").addEventListener("change",draw);
  document.getElementById("cq_c").addEventListener("change",draw);
  draw();
}


